/* Macro: two-column page */
.page {
  display: grid;
  grid-template-columns: 250px 1fr;
  gap: 1rem;
}

/* Responsive cards without media queries */
.cards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 1.5rem;
}

/* Micro: card internals flow on one line */
.card-header { display: flex; justify-content: space-between; }

.badge {
  position: absolute;      /* anchored to .card below */
  top: -8px; right: -8px;
  z-index: 2;
}
.card { position: relative; }

.header { position: sticky; top: 0; } /* sticks while scrolling */

.faded { opacity: 0.99; }  /* creates stacking context! */

/* The 2024+ answer: */
.parent {
  display: grid;
  place-items: center;   /* both axes, any child */
  min-height: 100dvh;
}

/* Overlay variant: */
.overlay-child {
  position: fixed;
  inset: 0;
  margin: auto;
  width: fit-content; height: fit-content;
}

/* Mobile base */
.features { display: grid; gap: 1rem; }

/* Tablet: two columns */
@media (min-width: 48rem) {
  .features { grid-template-columns: repeat(2, 1fr); }
}

/* Desktop: three + wider gutters */
@media (min-width: 64rem) {
  .features { grid-template-columns: repeat(3, 1fr); gap: 2rem; }
}

/* Pseudo-classes: states & positions */
.btn:hover { background: indigo; }
.btn:focus-visible { outline: 2px solid indigo; }
tr:nth-child(even) { background: #f5f5f5; }
.card:has(img) { padding-top: 0; }   /* parent responds to child */

/* Pseudo-elements: virtual content */
.required::after { content: " *"; color: red; }
::selection { background: indigo; color: white; }
